// Adult proportions, jointed motion and original period garments. The public
// geometry contains only clothed figures and the face/hand details used by them.
export const PERSON_PROPORTIONS=Object.freeze({height:1.78,headHeight:.245,eyeHeight:1.66,hipHeight:.94,shoulderHeight:1.43});
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
const materialCaches=new WeakMap();
const neutral=new T.Color();
function resource(world,key,make){const id='person:'+key;if(!world.geometries.has(id))world.geometries.set(id,make());return world.geometries.get(id);}
function material(world,key,color,parameters={}){const id='person:'+key+':'+color;if(!world.materials.has(id))world.materials.set(id,new T.MeshStandardMaterial({color,roughness:.86,metalness:0,...parameters}));return world.materials.get(id);}
function maps(world){if(materialCaches.has(world))return materialCaches.get(world);const make=(kind)=>{const n=128,data=new Uint8Array(n*n*4);let seed=kind==='skin'?137:431;for(let y=0;y<n;y++)for(let x=0;x<n;x++){seed=(1664525*seed+1013904223)>>>0;const noise=(seed>>>24)/255-.5;const weave=kind==='cloth'?Math.sin(x*Math.PI)*0+Math.cos(x*Math.PI/2)*8+Math.sin(y*Math.PI/2)*7:kind==='hair'?Math.sin(x*Math.PI/3+Math.sin(y*.09)*.55)*26:0;const value=clamp(128+noise*(kind==='skin'?42:25)+weave,0,255),i=(y*n+x)*4;data[i]=data[i+1]=data[i+2]=value;data[i+3]=255;}const tx=new T.DataTexture(data,n,n);tx.wrapS=tx.wrapT=T.RepeatWrapping;tx.repeat.set(kind==='skin'?3:5,kind==='skin'?3:7);tx.needsUpdate=true;world.textures.push(tx);return tx;};const value={skin:make('skin'),cloth:make('cloth'),hair:make('hair')};materialCaches.set(world,value);return value;}
function group(parent,x=0,y=0,z=0){const g=new T.Group();g.position.set(x,y,z);parent.add(g);return g;}
function mesh(parent,geometry,mat,x=0,y=0,z=0,cast=false){const m=new T.Mesh(geometry,mat);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}
function sphere(world,parent,mat,x,y,z,sx,sy,sz,detail=false,cast=false){const g=resource(world,'sphere-'+(detail?'high':'low'),()=>new T.SphereGeometry(1,detail?24:14,detail?18:10));const m=mesh(parent,g,mat,x,y,z,cast);m.scale.set(sx,sy,sz);return m;}

// Ring profiles produce continuous shoulders, waists, sleeves and garment folds
// rather than disconnected rigid boxes. Coordinates are metres.
export function profileGeometry(profile,segments=24,{folds=0,foldAmount=0}={}){
 // Dense, slope-limited rings soften the silhouette without swelling cuffs or
 // producing the sharp chest/shoulder bands of the low-ring construction.
 if(profile.length>3){const source=profile,rows=[];for(let i=0;i<source.length-1;i++){const a=source[i],b=source[i+1],dy=b[0]-a[0];for(let k=0;k<4;k++){const t=k/4,row=[a[0]+dy*t];for(let axis=1;axis<3;axis++){const slope=(b[axis]-a[axis])/dy,prev=i?(a[axis]-source[i-1][axis])/(a[0]-source[i-1][0]):slope,next=i<source.length-2?(source[i+2][axis]-b[axis])/(source[i+2][0]-b[0]):slope;const m0=prev*slope>0?Math.sign(slope)*Math.min(Math.abs(prev),Math.abs(slope)):0,m1=next*slope>0?Math.sign(slope)*Math.min(Math.abs(next),Math.abs(slope)):0;row.push((2*t*t*t-3*t*t+1)*a[axis]+(t*t*t-2*t*t+t)*dy*m0+(-2*t*t*t+3*t*t)*b[axis]+(t*t*t-t*t)*dy*m1);}rows.push(row);}}rows.push(source.at(-1));profile=rows;}
 const positions=[],uv=[],indices=[];const y0=profile[0][0],dy=profile[profile.length-1][0]-y0;
 for(let i=0;i<profile.length;i++){const [y,rx,rz]=profile[i];for(let j=0;j<=segments;j++){const theta=j/segments*Math.PI*2,fold=1+Math.cos(theta*folds)*(folds?foldAmount:0);positions.push(Math.sin(theta)*rx*fold,y,Math.cos(theta)*rz*fold);uv.push(j/segments,(y-y0)/dy);}}
 for(let i=0;i<profile.length-1;i++)for(let j=0;j<segments;j++){const a=i*(segments+1)+j,b=a+1,c=a+segments+1,d=c+1;indices.push(a,b,c,b,d,c);}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();return g;
}
function profile(world,key,parent,mat,rows,segments=24,folds=0,amount=0,cast=false){return mesh(parent,resource(world,key,()=>profileGeometry(rows,segments,{folds,foldAmount:amount})),mat,0,0,0,cast);}
function curve(world,key,parent,mat,points,radius=.002,cast=false){const geo=resource(world,key,()=>new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),Math.max(6,points.length*3),radius,5,false));return mesh(parent,geo,mat,0,0,0,cast);}
