  const neck=clamp((-.075-y)/.07,0,1);x+=(clamp(x,-.039,.039)-x)*neck;z+=(clamp(z,-.035,.047)-z)*neck;
  positions[i]=x;positions[i+1]=y;positions[i+2]=z;uv.push(.5+Math.atan2(x,z)/Math.PI/2,(y+.16)/.31);
