  const variationNoise=Math.sin(x*317+y*227+z*181)*Math.sin(x*131-y*371)*.007;
  colors.push(1+cheeks*.020-lips*.025-lids*.026-nostril*.11+variationNoise,1-cheeks*.052-lips*.17-lids*.075-nostril*.15-beard*.025+variationNoise,1-cheeks*.040-lips*.14-lids*.055-nostril*.14-beard*.018+variationNoise);
